checker.setup:
def conv_output_size(size, kernel_size, stride=1, padding=0):
    if min(size, kernel_size, stride) < 1 or padding < 0:
        raise ValueError("invalid sizes")
    out = (size + 2 * padding - kernel_size) // stride + 1
    if out < 1:
        raise ValueError("kernel does not fit")
    return out

